// ── Open blob in new tab and trigger print ────────────────────────────────────
const printCreditNote = (note) => {
  const html = buildCreditNoteHTML(note);
  const blob = new Blob([html], { type: 'text/html' });
  const url = URL.createObjectURL(blob);
  const win = window.open(url, '_blank');
  if (win) win.onload = () => setTimeout(() => win.print(), 600);
  setTimeout(() => URL.revokeObjectURL(url), 60000);
};

const netAmount = (items, taxType) => {
  const sub = items.reduce((s, it) => s + (Number(it.qty || 0) * Number(it.price || 0)), 0);
  return taxType === 'SEZ' ? sub : sub * 1.18;
};

const TaxBadge = ({ taxType }) => (
  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-semibold ${taxType === 'SEZ' ? 'bg-blue-500/10 text-blue-400' : 'bg-emerald-500/10 text-[#6ee7b7]'}`}>
    {taxType === 'SEZ' ? 'SEZ/Export' : 'GST 18%'}
  </span>
);

